def fibonacci(n):
    a, b = 0, 1
    for _ in range(n):
        yield a
        a, b = b, a + b

memo = {}
def factorial(n):
    if n in (0, 1):
        return 1
    if n not in memo:
        memo[n] = n * factorial(n - 1)
    return memo[n]

